def count_pairs(nums, target):
    """Number of index pairs (i, j) with i < j and nums[i] + nums[j] == target."""
    seen = {}
    count = 0
    for x in nums:
        count += seen.get(target - x, 0)
        seen[x] = seen.get(x, 0) + 1
    return count

